<?php
declare(strict_types=1);
namespace Tests\Integration;
use PDO;use PHPUnit\Framework\TestCase;
require_once dirname(__DIR__,2).'/includes/club_cutover.php';
final class ClubCutoverTest extends TestCase
{
 private function db(bool$complete=true):PDO{$p=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$p->exec('PRAGMA foreign_keys=ON;CREATE TABLE treneri(id INTEGER PRIMARY KEY,aktivni INTEGER);CREATE TABLE staff_user_positions(trainer_id INTEGER,position_code TEXT);CREATE TABLE staff_superadmins(trainer_id INTEGER);INSERT INTO treneri VALUES(1,1),(2,1)');$p->exec("INSERT INTO staff_user_positions VALUES(1,'system_admin'),(2,'coach')");$m=require dirname(__DIR__,2).'/migrations/20261023090000_club_cutover.php';$m['up']($p);self::assertTrue($m['verify']($p));if($complete)foreach(\clubCutoverCriticalTables()as$table=>$key)$p->exec('CREATE TABLE IF NOT EXISTS '.$table.'('.$key.' INTEGER PRIMARY KEY,value TEXT,amount_minor INTEGER)');return$p;}
 private function create(PDO$p):int{return \clubCutoverCreate($p,1,['title'=>'LOCALHOST rehearsal','scope_text'=>'LOCALHOST one sports group and allocated shop stock','release_reference'=>'LOCALHOST source revision','source_environment'=>'LOCALHOST old source','target_environment'=>'http://localhost:18086','owner_trainer_id'=>1]);}
 private function source():array{return['entry_key'=>'source:old','kind'=>'source','title'=>'LOCALHOST Evidence','owner_trainer_id'=>1,'evidence'=>'LOCALHOST declared ownership; not real acceptance','origin'=>'https://old.example.invalid/evidence/','history_mode'=>'active','shutdown_condition'=>'LOCALHOST archive, no unsettled cases, explicit owner decision'];}
 private function reject(callable$f):void{try{$f();self::fail('Expected refusal');}catch(\DomainException$e){self::assertNotSame('',$e->getMessage());}}
 public function testEntriesImmutableAndStaleRevisionCannotOverwrite():void{$p=$this->db();$run=$this->create($p);$id=\clubCutoverEntry($p,1,$run,0,$this->source(),'LOCALHOST initial');$before=$p->query('SELECT * FROM club_cutover_entries WHERE id='.$id)->fetch();$this->reject(fn()=>\clubCutoverEntry($p,1,$run,0,$this->source(),'LOCALHOST stale'));$input=$this->source();$input['history_mode']='archive';\clubCutoverEntry($p,1,$run,1,$input,'LOCALHOST corrected source decision');self::assertSame($before,$p->query('SELECT * FROM club_cutover_entries WHERE id='.$id)->fetch());self::assertSame('archive',\clubCutoverEntries($p,$run)['source:old']['data']['history_mode']);}
 public function testActualCaptureDetectsNewChangedRemovedOperationsAndPreservesEvidence():void{$p=$this->db();$run=$this->create($p);$p->exec("INSERT INTO accounting_movements VALUES(1,'ORIGINAL',10000),(2,'OLD',5000)");$checkpoint=\clubCutoverCheckpoint($p,1,$run,0,'LOCALHOST before operations','LOCALHOST baseline');$before=\clubCutoverCheckpointGet($p,$checkpoint);$p->exec("INSERT INTO accounting_movements VALUES(3,'NEW',5000);UPDATE accounting_movements SET value='CORRECTED' WHERE id=1;DELETE FROM accounting_movements WHERE id=2");$preview=\clubCutoverPreview($p,1,$run,$checkpoint,'G3');self::assertSame(1,$preview['delta']['added']);self::assertSame(1,$preview['delta']['changed']);self::assertSame(1,$preview['delta']['removed']);self::assertFalse($preview['production_authorized']);self::assertSame('preserve_new_operations_then_forward_fix_or_controlled_return',$preview['delta']['rollback_mode']);self::assertFalse($preview['delta']['restore_executable']);$review=\clubCutoverReview($p,1,$run,$checkpoint,'G3','LOCALHOST preserve post-opening delta');$json=$p->query('SELECT result_json FROM club_cutover_reviews WHERE id='.$review)->fetchColumn();self::assertStringNotContainsString('CORRECTED',$json);self::assertSame($before,\clubCutoverCheckpointGet($p,$checkpoint));self::assertSame(2,(int)$p->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());}
 public function testMissingTablesAndHumanAssertionsNeverGrantProductionApproval():void{$p=$this->db(false);$run=$this->create($p);$checkpoint=\clubCutoverCheckpoint($p,1,$run,0,'LOCALHOST incomplete','LOCALHOST missing data');foreach(['G0','G1','G2','G3','G4','G5','G6']as$gate){$r=\clubCutoverPreview($p,1,$run,$checkpoint,$gate);self::assertSame('blocked',$r['status']);self::assertSame('unknown',$r['human_acceptance']);self::assertFalse($r['production_authorized']);self::assertNotEmpty($r['delta']['unknown']);}}
 public function testUrlsRequireDeclaredSourceAndTargetAndRejectSecretParameters():void{$p=$this->db();$run=$this->create($p);\clubCutoverEntry($p,1,$run,0,$this->source(),'LOCALHOST');$url=['entry_key'=>'url:one','kind'=>'url','title'=>'LOCALHOST page','owner_trainer_id'=>1,'evidence'=>'LOCALHOST map','source_key'=>'source:old','old_url'=>'https://old.example.invalid/evidence/info','new_url'=>'http://localhost:18086/info','access_mode'=>'public','handling'=>'redirect'];\clubCutoverEntry($p,1,$run,1,$url,'LOCALHOST proposal only');foreach([['old_url'=>'https://attacker.invalid/path'],['new_url'=>'https://attacker.invalid/path'],['old_url'=>'https://old.example.invalid/private?token=secret'],['access_mode'=>'private']]as$change)$this->reject(fn()=>\clubCutoverEntry($p,1,$run,2,array_replace($url,$change),'LOCALHOST invalid map'));self::assertSame(2,(int)\clubCutoverRun($p,$run)['revision']);}
 public function testAttachmentHashMustMatchActualCanonicalPrivateFile():void{$p=$this->db(false);$p->exec('CREATE TABLE financial_decisions(id INTEGER PRIMARY KEY,storage_key TEXT,file_sha256 TEXT)');$root=sys_get_temp_dir().'/cutover-test-'.bin2hex(random_bytes(5));mkdir($root);mkdir($root.'/accounting-documents');$old=getenv('APP_PRIVATE_STORAGE_ROOT');putenv('APP_PRIVATE_STORAGE_ROOT='.$root);$name=str_repeat('a',32).'.pdf';$bytes='%PDF-1.4 LOCALHOST synthetic proof';file_put_contents($root.'/accounting-documents/'.$name,$bytes);$hash=hash('sha256',$bytes);$p->prepare('INSERT INTO financial_decisions VALUES(1,?,?)')->execute(['private://accounting-documents/'.$name,$hash]);$data=['record_type'=>'expense_decision','record_id'=>1,'expected_sha256'=>$hash,'access_mode'=>'private'];try{self::assertSame('verified_bytes',\clubCutoverVerifyAttachment($p,$data)['status']);$bad=$data;$bad['expected_sha256']=str_repeat('b',64);self::assertSame('failed',\clubCutoverVerifyAttachment($p,$bad)['status']);unlink($root.'/accounting-documents/'.$name);self::assertSame('failed',\clubCutoverVerifyAttachment($p,$data)['status']);}finally{putenv($old===false?'APP_PRIVATE_STORAGE_ROOT':'APP_PRIVATE_STORAGE_ROOT='.$old);if(is_file($root.'/accounting-documents/'.$name))unlink($root.'/accounting-documents/'.$name);rmdir($root.'/accounting-documents');rmdir($root);}}
 public function testRoleRevocationBlocksServiceCallsAndCheckpointIsBoundToRun():void{$p=$this->db();$run=$this->create($p);$checkpoint=\clubCutoverCheckpoint($p,1,$run,0,'LOCALHOST','LOCALHOST');$other=$this->create($p);$this->reject(fn()=>\clubCutoverPreview($p,1,$other,$checkpoint,'G0'));$this->reject(fn()=>\clubCutoverEntry($p,2,$run,0,$this->source(),'LOCALHOST denied'));$p->exec('DELETE FROM staff_user_positions WHERE trainer_id=1');$this->reject(fn()=>\clubCutoverPreview($p,1,$run,$checkpoint,'G0'));}
 public function testBinaryCellsAndDuplicateRowsWithoutPrimaryKeyRemainExact():void{$p=$this->db();$p->exec('DROP TABLE club_event_notifications;CREATE TABLE club_event_notifications(payload BLOB)');$q=$p->prepare('INSERT INTO club_event_notifications VALUES(?)');$q->execute(["\xff\0\x80"]);$q->execute(["\xff\0\x80"]);$a=\clubCutoverCapture($p);self::assertSame(2,$a['tables']['club_event_notifications']['count']);self::assertCount(2,$a['tables']['club_event_notifications']['rows']);$p->exec('DELETE FROM club_event_notifications WHERE rowid=1');$b=\clubCutoverCapture($p);$delta=\clubCutoverDelta($a,$b);self::assertSame(1,$delta['removed']);self::assertSame(0,$delta['changed']);}
 public function testActualSchemaChangeIsBlockedEvenWhenRowCountsMatch():void{$p=$this->db();$a=\clubCutoverCapture($p);$p->exec('ALTER TABLE payments ADD COLUMN provider_update TEXT');$b=\clubCutoverCapture($p);$delta=\clubCutoverDelta($a,$b);self::assertContains('payments',$delta['schema_changed']);self::assertSame('blocked_unknown',$delta['rollback_mode']);self::assertFalse($delta['restore_executable']);}
 public function testDeferredReviewCanHaveFutureDateAndInactiveOwnerIsRejected():void{$p=$this->db();$run=$this->create($p);$input=['entry_key'=>'check:future','kind'=>'check','title'=>'LOCALHOST future review','owner_trainer_id'=>2,'evidence'=>'LOCALHOST unresolved manual check','scenario'=>'P24','result'=>'deferred','review_on'=>'2099-01-01'];\clubCutoverEntry($p,1,$run,0,$input,'LOCALHOST future deadline');self::assertSame('2099-01-01',\clubCutoverEntries($p,$run)['check:future']['data']['review_on']);$bad=$input;$bad['review_on']='2026-02-30';$this->reject(fn()=>\clubCutoverEntry($p,1,$run,1,$bad,'LOCALHOST invalid calendar date'));$p->exec('UPDATE treneri SET aktivni=0 WHERE id=2');$this->reject(fn()=>\clubCutoverEntry($p,1,$run,1,$input,'LOCALHOST inactive owner'));self::assertSame(1,(int)\clubCutoverRun($p,$run)['revision']);}
}
